    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C135","C162","C153","C160","C165","C157","C148","C154","C159","C167","C143","C181","C174","C142","C171","C178"]
    },
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C138","C132","C140","C158","C145","C149"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for guanosine itself is supplied.",
    "No guanosine-specific permeability or transporter-uptake record is supplied; L4 records are for nucleoside analogs.",
    "Nucleoside transporter involvement (CNT/ENT) and purine nucleoside phosphorylase/adenosine deaminase metabolism are not directly assessed.",
    "Acyclovir F=20% sits exactly at the threshold, leaving boundary uncertainty.",
    "L3 AUC/Cmax records lack matched IV comparators, so they cannot quantify absolute F.",
    "Caco-2/PAMPA low permeability may underestimate transporter-mediated absorption for nucleosides."
  ],
  "decision_summary": "L4 low passive permeability records for nucleoside analogs temper but do not overturn the high prediction. Direct F records for nucleoside analogs (ddA 38%, ddI 30–54%, emtricitabine 92%, acyclovir 20%) and L3 oral exposure remain more direct; low Caco-2/PAMPA values are not affirmative F<20% evidence, especially where the same analogs show F>=20%. Prediction remains high with moderate confidence."
}

